/// 原子写文件——先写同目录 tmp 再 rename 覆盖目标（Windows 走 ReplaceExisting 语义）
pub(crate) fn atomic_write(path: &std::path::Path, contents: &str) -> Result<(), String> {
    let file_name = path
        .file_name()
        .ok_or_else(|| format!("无效的目标路径：{}", path.display()))?;
    let tmp = path.with_file_name(format!("{}.tmp", file_name.to_string_lossy()));
    std::fs::write(&tmp, contents).map_err(|e| format!("写入临时文件失败：{e}"))?;
    // Windows 下 std::fs::rename 不会覆盖已存在文件——必须先 remove 目标或换 API；
    // 否则旧版升级场景会因目标已存在而 fail-closed，留下陈旧内容。
    #[cfg(windows)]
    {
        let _ = std::fs::remove_file(path); // 删目标后 rename 一定成功，但有极短空窗
        std::fs::rename(&tmp, path).map_err(|e| {
            let _ = std::fs::remove_file(&tmp);
            format!("落盘重命名失败：{e}")
        })?;
    }
    #[cfg(not(windows))]
    std::fs::rename(&tmp, path).map_err(|e| {
        let _ = std::fs::remove_file(&tmp);
        format!("落盘重命名失败：{e}")
    })?;
    Ok(())
}

